test('searchTodos should prevent SQL injection attacks', async () => {
  const maliciousKeyword = "'; DROP TABLE todos; --";
  const result = await searchTodos(maliciousKeyword);
  // Verify the function safely escapes or parameterizes the input
  const allTodos = await getAllTodos();
  expect(allTodos.length).toBeGreaterThan(0); // Table should still exist
});

test('searchTodosByStatus should prevent SQL injection', async () => {
  const maliciousInput = "1 OR 1=1";
  const result = await searchTodosByStatus(maliciousInput);
  // Verify parameterized query prevents injection
  expect(Array.isArray(result)).toBe(true);
});

test('getTodosByUser should prevent SQL injection and maintain user isolation', async () => {
  const userId1 = 'user1';
  const userId2 = 'user2';
  const todos1 = await getTodosByUser(userId1);
  const todos2 = await getTodosByUser(userId2);
  // Verify each user only sees their todos
  expect(todos1.length).toBeGreaterThan(0);
  expect(todos2.length).toBeGreaterThan(0);
  // Verify different users get different results
  expect(todos1[0].id).not.toEqual(todos2[0]?.id);
});

test('validateTodoInput should validate all rules', () => {
  expect(validateTodoInput({ title: '', description: '' })).toBe(false);
  expect(validateTodoInput({ title: 'a'.repeat(201), description: '' })).toBe(false);
  expect(validateTodoInput({ title: 'Valid', description: 'a'.repeat(1001) })).toBe(false);
  expect(validateTodoInput({ title: 'Valid', description: 'Valid' })).toBe(true);
});

test('sanitizeInput should escape HTML entities', () => {
  expect(sanitizeInput('<script>alert(1)</script>')).toBe('&lt;script&gt;alert(1)&lt;/script&gt;');
  expect(sanitizeInput('"quotes" and \'apostrophes\'')).toBe('&quot;quotes&quot; and &#039;apostrophes&#039;');
});

test('createTodo should create and sanitize todo', async () => {
  const result = await createTodo({ title: '<script>alert(1)</script>', description: 'Test' });
  expect(result.title).toBe('&lt;script&gt;alert(1)&lt;/script&gt;');
  expect(result.completed).toBe(false);
});

test('getAllTodos should return todos ordered by created_at DESC', async () => {
  const todos = await getAllTodos();
  expect(Array.isArray(todos)).toBe(true);
  // Verify descending order
  for (let i = 0; i < todos.length - 1; i++) {
    expect(todos[i].createdAt >= todos[i + 1].createdAt).toBe(true);
  }
});

test('getTodoById should return todo or null', async () => {
  const result = await getTodoById('nonexistent');
  expect(result).toBeNull();
});

test('updateTodoStatus should update todo status', async () => {
  const todo = await getTodoById('test-id');
  await updateTodoStatus('test-id', !todo.completed);
  const updated = await getTodoById('test-id');
  expect(updated.completed).toBe(!todo.completed);
});

test('deleteTodo should remove todo from database', async () => {
  const todo = await createTodo({ title: 'To Delete', description: '' });
  await deleteTodo(todo.id);
  const result = await getTodoById(todo.id);
  expect(result).toBeNull();
});

test('searchTodos should handle SQL wildcard characters', async () => {
  // Test with % and _ which have special meaning in LIKE
  const result = await searchTodos('test%value');
  // Should match exact pattern, not treat % as wildcard
  expect(result.every(t => t.title.includes('test') || t.description.includes('test'))).toBe(true);
});

test('searchTodos should handle empty keyword', async () => {
  const result = await searchTodos('');
  // Should either return empty array or all todos based on design
  expect(Array.isArray(result)).toBe(true);
});

test('sanitizeInput should handle null/undefined safely', () => {
  expect(() => sanitizeInput(null as any)).toThrow();
  expect(() => sanitizeInput(undefined as any)).toThrow();
});

test('createTodo should throw on invalid input', async () => {
  expect(async () => {
    await createTodo({ title: '', description: '' });
  }).rejects.toThrow('Invalid todo input');
});

